with open('/workdir/disk.img', 'rb') as f:
    data = f.read()

# Find all non-zero bytes
non_zero = []
for i, byte in enumerate(data):
    if byte != 0:
        non_zero.append((i, byte))

# Print first 20 non-zero occurrences
for pos, val in non_zero[:20]:
    print(f'Position {pos}: {hex(val)}')
